import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Version 1.0.0.38 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.38-released.md","filePath":"change-log/release/version-1.0.0.38-released.md"}'),o={name:"change-log/release/version-1.0.0.38-released.md"};function n(l,e,s,d,u,h){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="version-1-0-0-38-released" tabindex="-1">Version 1.0.0.38 Released <a class="header-anchor" href="#version-1-0-0-38-released" aria-label="Permalink to &quot;Version 1.0.0.38 Released&quot;">​</a></h1><p>Version <strong>1.0.0.38</strong> is a feature-heavy release focused on <strong>Options Trading APIs</strong>, <strong>Python 3.14 compatibility</strong>, <strong>Playground upgrades</strong>, <strong>WebSocket improvements</strong>, and <strong>major broker updates</strong>.<br> This is also the release where <strong>OptionMultiOrder</strong> becomes production-ready.</p><hr><h2 id="major-feature-updates" tabindex="-1"><strong>Major Feature Updates</strong> <a class="header-anchor" href="#major-feature-updates" aria-label="Permalink to &quot;**Major Feature Updates**&quot;">​</a></h2><h3 id="_1-optionsmultiorder-–-calendar-diagonal-multi-expiry-support" tabindex="-1"><strong>1. OptionsMultiOrder – Calendar, Diagonal, Multi-Expiry Support</strong> <a class="header-anchor" href="#_1-optionsmultiorder-–-calendar-diagonal-multi-expiry-support" aria-label="Permalink to &quot;**1. OptionsMultiOrder – Calendar, Diagonal, Multi-Expiry Support**&quot;">​</a></h3><ul><li>OptionsMultiOrder now supports <strong>different expiries</strong> for each leg.</li><li>Enables <strong>Calendar Spreads</strong>, <strong>Diagonal Spreads</strong>, <strong>Multi-expiry Condors</strong>, etc.</li><li>Underlying LTP handling improved (None-type issues fixed).</li><li>Multi-leg duplication bug removed.</li></ul><h3 id="_2-synthetic-futures-api" tabindex="-1"><strong>2. Synthetic Futures API</strong> <a class="header-anchor" href="#_2-synthetic-futures-api" aria-label="Permalink to &quot;**2. Synthetic Futures API**&quot;">​</a></h3><ul><li>New lightweight API to generate <strong>Synthetic Futures</strong> using CE/PE combos.</li><li>Faster than computing spreads manually.</li><li>Part of the expanding derivatives toolkit.</li></ul><h3 id="_3-strikes-lookup-cache" tabindex="-1"><strong>3. Strikes Lookup Cache</strong> <a class="header-anchor" href="#_3-strikes-lookup-cache" aria-label="Permalink to &quot;**3. Strikes Lookup Cache**&quot;">​</a></h3><ul><li>Implemented <strong>in-memory caching</strong> for near-instant strike discovery.</li><li>Massive performance boost for OptionsOrder, OptionsSymbol, OptionsMultiOrder.</li></ul><h3 id="_4-python-3-14-compatibility" tabindex="-1"><strong>4. Python 3.14 Compatibility</strong> <a class="header-anchor" href="#_4-python-3-14-compatibility" aria-label="Permalink to &quot;**4. Python 3.14 Compatibility**&quot;">​</a></h3><ul><li>Tradeboard Python SDK upgraded to <strong>v1.0.38</strong>.</li><li>Ensures clean installs on macOS, Windows, Linux.</li><li>Fixes around dependency chain and wheel compatibility.</li></ul><h3 id="_5-api-playground-–-major-refresh" tabindex="-1"><strong>5. API Playground – Major Refresh</strong> <a class="header-anchor" href="#_5-api-playground-–-major-refresh" aria-label="Permalink to &quot;**5. API Playground – Major Refresh**&quot;">​</a></h3><ul><li>Alphabetical sorting for endpoints.</li><li>Modern UI with cleaner validation.</li><li>Request builder improvements.</li><li>Local assets only (no CDN usage).</li><li>Ability to load endpoints directly from Bruno files.</li><li>New playground.js with improved utilities.</li><li>NavBar cleaned (playground removed from top nav and moved to Tools section).</li></ul><h3 id="_6-security-improvements" tabindex="-1"><strong>6. Security Improvements</strong> <a class="header-anchor" href="#_6-security-improvements" aria-label="Permalink to &quot;**6. Security Improvements**&quot;">​</a></h3><ul><li>Multiple <strong>security documentation updates</strong>.</li><li>IDor vulnerability fixes.</li><li>Removed unused <code>login_required</code> decorators.</li><li>Safer routing between POST and GET usage.</li></ul><hr><h2 id="broker-wise-enhancements" tabindex="-1"><strong>Broker-wise Enhancements</strong> <a class="header-anchor" href="#broker-wise-enhancements" aria-label="Permalink to &quot;**Broker-wise Enhancements**&quot;">​</a></h2><h3 id="motilal-oswal" tabindex="-1"><strong>Motilal Oswal</strong> <a class="header-anchor" href="#motilal-oswal" aria-label="Permalink to &quot;**Motilal Oswal**&quot;">​</a></h3><ul><li>MCX Options master scrip symbol issue fixed.</li></ul><h3 id="mstock" tabindex="-1"><strong>MStock</strong> <a class="header-anchor" href="#mstock" aria-label="Permalink to &quot;**MStock**&quot;">​</a></h3><ul><li>History API fixes.</li><li>Index values corrected in master contract.</li><li>OA exchange mapping fixed in orderbook, tradebook, positionbook.</li><li>Net P&amp;L in positionbook corrected.</li></ul><h3 id="dhan" tabindex="-1"><strong>Dhan</strong> <a class="header-anchor" href="#dhan" aria-label="Permalink to &quot;**Dhan**&quot;">​</a></h3><ul><li>Depth-level WebSocket: 5-level and 20-level depth fully activated.</li><li>depth_level parameter bug fixed.</li><li>WebSocket unsubscribe_all fixed.</li></ul><h3 id="fyers" tabindex="-1"><strong>Fyers</strong> <a class="header-anchor" href="#fyers" aria-label="Permalink to &quot;**Fyers**&quot;">​</a></h3><ul><li>TBT (Tick-by-Tick) WebSocket unsubscription fixed.</li><li>TBT 50-level depth update implemented.</li></ul><h3 id="indmoney" tabindex="-1"><strong>IndMoney</strong> <a class="header-anchor" href="#indmoney" aria-label="Permalink to &quot;**IndMoney**&quot;">​</a></h3><ul><li>LTP WebSocket improved.</li><li>Tradebook updated.</li></ul><h3 id="kotak" tabindex="-1"><strong>Kotak</strong> <a class="header-anchor" href="#kotak" aria-label="Permalink to &quot;**Kotak**&quot;">​</a></h3><ul><li>Margin API updated.</li></ul><h3 id="groww" tabindex="-1"><strong>Groww</strong> <a class="header-anchor" href="#groww" aria-label="Permalink to &quot;**Groww**&quot;">​</a></h3><ul><li>Margin API updated.</li></ul><h3 id="zebu" tabindex="-1"><strong>Zebu</strong> <a class="header-anchor" href="#zebu" aria-label="Permalink to &quot;**Zebu**&quot;">​</a></h3><ul><li>Margin API updated (broker does not support margin; aligned accordingly).</li></ul><h3 id="tradejini" tabindex="-1"><strong>TradeJini</strong> <a class="header-anchor" href="#tradejini" aria-label="Permalink to &quot;**TradeJini**&quot;">​</a></h3><ul><li>Margin API updated (non-margin broker standardization).</li></ul><h3 id="paytm-money" tabindex="-1"><strong>PayTM Money</strong> <a class="header-anchor" href="#paytm-money" aria-label="Permalink to &quot;**PayTM Money**&quot;">​</a></h3><ul><li>Margin API cleaned (non-margin broker standardization).</li></ul><h3 id="fivepaisa" tabindex="-1"><strong>Fivepaisa</strong> <a class="header-anchor" href="#fivepaisa" aria-label="Permalink to &quot;**Fivepaisa**&quot;">​</a></h3><ul><li>Margin API updated.</li></ul><h3 id="firstock" tabindex="-1"><strong>Firstock</strong> <a class="header-anchor" href="#firstock" aria-label="Permalink to &quot;**Firstock**&quot;">​</a></h3><ul><li>Margin API updated.</li></ul><h3 id="definedge" tabindex="-1"><strong>Definedge</strong> <a class="header-anchor" href="#definedge" aria-label="Permalink to &quot;**Definedge**&quot;">​</a></h3><ul><li>Margin API updated.</li></ul><h3 id="aliceblue" tabindex="-1"><strong>AliceBlue</strong> <a class="header-anchor" href="#aliceblue" aria-label="Permalink to &quot;**AliceBlue**&quot;">​</a></h3><ul><li>Margin API updated.</li></ul><hr><h2 id="execution-engine-improvements" tabindex="-1"><strong>Execution &amp; Engine Improvements</strong> <a class="header-anchor" href="#execution-engine-improvements" aria-label="Permalink to &quot;**Execution &amp; Engine Improvements**&quot;">​</a></h2><h3 id="_1-options-engine" tabindex="-1"><strong>1. Options Engine</strong> <a class="header-anchor" href="#_1-options-engine" aria-label="Permalink to &quot;**1. Options Engine**&quot;">​</a></h3><ul><li>Multi-quote fix added for underlying price fetch.</li><li>strike_int parameter removed from OptionsOrder and OptionSymbol (optional for backward compatibility only).</li></ul><h3 id="_2-websockets" tabindex="-1"><strong>2. WebSockets</strong> <a class="header-anchor" href="#_2-websockets" aria-label="Permalink to &quot;**2. WebSockets**&quot;">​</a></h3><ul><li>Improved depth streaming and TBT stability.</li><li>Memory cleanup in WebSocket pipelines.</li><li>Logging noise heavily reduced.</li></ul><h3 id="_3-sandbox-fixes" tabindex="-1"><strong>3. Sandbox Fixes</strong> <a class="header-anchor" href="#_3-sandbox-fixes" aria-label="Permalink to &quot;**3. Sandbox Fixes**&quot;">​</a></h3><ul><li>Race condition issue in parallel order placement fixed.</li><li>SmartOrder sandbox bug resolved earlier in 1.0.0.37, reinforced here.</li></ul><hr><h2 id="latency-storage-optimizations" tabindex="-1"><strong>Latency &amp; Storage Optimizations</strong> <a class="header-anchor" href="#latency-storage-optimizations" aria-label="Permalink to &quot;**Latency &amp; Storage Optimizations**&quot;">​</a></h2><ul><li>Latency monitoring optimized.</li><li>Requests and Responses trimmed to <strong>NULL</strong> inside latency.db to prevent DB bloat.</li><li>Database writes reduced significantly.</li></ul><hr><h2 id="ui-ux-and-misc-updates" tabindex="-1"><strong>UI, UX, and Misc Updates</strong> <a class="header-anchor" href="#ui-ux-and-misc-updates" aria-label="Permalink to &quot;**UI, UX, and Misc Updates**&quot;">​</a></h2><ul><li>Password strength validation added.</li><li>Navbar improved using flex alignment.</li><li>Removed theme toggle from Playground (simplified UI).</li><li>Updated DaisyUI compiled CSS.</li><li>Fixed multiple mapping issues across the platform.</li><li>README updated with latest examples and SDK instructions.</li></ul><hr><h2 id="summary" tabindex="-1"><strong>Summary</strong> <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;**Summary**&quot;">​</a></h2><p>Version <strong>1.0.0.38</strong> delivers critical upgrades across the entire stack:</p><ul><li>OptionsMultiOrder now supports <strong>multi-expiry spreads</strong></li><li>Python SDK fully compatible with <strong>Python 3.14</strong></li><li>Playground modern UI, utilities, security, and performance</li><li>Synthetic Futures API added</li><li>Huge batch of <strong>Margin API</strong> updates</li><li>Improved <strong>WebSocket depth, TBT, and data pipelines</strong></li><li>Multiple <strong>MStock</strong>, <strong>Dhan</strong>, <strong>Fyers</strong>, <strong>IndMoney</strong>, and <strong>Motilal</strong> fixes</li><li>DB trimming + latency monitoring optimization</li></ul><p>This release focuses on <strong>speed, reliability, and advanced options workflow automation</strong>.</p>',65)])])}const p=a(o,[["render",n]]);export{g as __pageData,p as default};
